# Optional Caddy or nginx in front of the loopback API, with HTTPS.

render_caddyfile() {
  local domain=$1 api_port=$2
  cat <<EOF
# Generated by scripts/install.sh. Re-running the installer replaces this file.
${domain} {
	encode gzip
	reverse_proxy 127.0.0.1:${api_port} {
		# Replace, do not append, so a client cannot supply 127.0.0.1.
		header_up X-Forwarded-For {remote_host}
		header_up X-Forwarded-Proto {scheme}
		header_up X-Forwarded-Host {host}
		flush_interval -1
		transport http {
			read_timeout 30m
			write_timeout 30m
		}
	}
}
EOF
}

render_nginx_site() {
  local domain=$1 api_port=$2
  cat <<EOF
# Generated by scripts/install.sh. Re-running the installer replaces this file.
server {
    listen 80;
    listen [::]:80;
    server_name ${domain};

    client_max_body_size 0;
    proxy_read_timeout 30m;
    proxy_send_timeout 30m;

    location / {
        proxy_pass http://127.0.0.1:${api_port};
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        # nginx's \$proxy_add_x_forwarded_for appends to a client-supplied
        # value. \$remote_addr is the address nginx accepted, which is what
        # the API key gate must see.
        proxy_set_header X-Forwarded-For \$remote_addr;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
        proxy_buffering off;
    }
}
EOF
}

install_caddy() {
  if command -v caddy >/dev/null 2>&1; then
    log "caddy $(caddy version 2>/dev/null | head -n 1) already installed"
    return
  fi
  log "Installing Caddy"
  apt-get install -y -qq debian-keyring debian-archive-keyring apt-transport-https curl gnupg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' \
    | gpg --dearmor -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' \
    > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -qq
  apt-get install -y -qq caddy
  # Our unit runs Caddy. The package unit would also bind 80/443.
  if systemd_running; then
    systemctl disable --now caddy.service >/dev/null 2>&1 || true
  fi
}

install_nginx() {
  if ! command -v nginx >/dev/null 2>&1; then
    log "Installing nginx"
    apt-get install -y -qq nginx
  else
    log "nginx already installed"
  fi
  # Connection upgrade map, once.
  if ! grep -q 'map \$http_upgrade \$connection_upgrade' /etc/nginx/nginx.conf 2>/dev/null; then
    if ! [ -f /etc/nginx/conf.d/voicestudio-upgrade.conf ]; then
      cat >/etc/nginx/conf.d/voicestudio-upgrade.conf <<'EOF'
map $http_upgrade $connection_upgrade {
    default upgrade;
    ''      close;
}
EOF
    fi
  fi
  rm -f /etc/nginx/sites-enabled/default
}

write_tls_config() {
  local domain=$1 tls=$2 api_port=$3 email=$4
  case "$tls" in
    caddy)
      install_caddy
      render_caddyfile "$domain" "$api_port" >"${VOICESTUDIO_DEFAULT_ETC}/Caddyfile"
      ;;
    nginx)
      install_nginx
      render_nginx_site "$domain" "$api_port" >"/etc/nginx/sites-available/voicestudio"
      ln -sfn /etc/nginx/sites-available/voicestudio /etc/nginx/sites-enabled/voicestudio
      nginx -t
      if [ -n "$email" ] && command -v certbot >/dev/null 2>&1 || [ -n "$email" ]; then
        if ! command -v certbot >/dev/null 2>&1; then
          apt-get install -y -qq certbot python3-certbot-nginx
        fi
        # Certificate issuance needs public DNS and port 80. A failure here
        # leaves the HTTP site in place so the operator can see the error.
        if systemd_running; then
          systemctl enable --now nginx.service
        else
          nginx
        fi
        certbot --nginx -d "$domain" --non-interactive --agree-tos -m "$email" --redirect \
          || log "certbot did not obtain a certificate. DNS for ${domain} must point at this machine and port 80 must be reachable. The HTTP site is still configured."
      else
        log "nginx is serving http://${domain}. Pass --email you@example.com to request a Let's Encrypt certificate."
      fi
      ;;
    *)
      die "Unknown TLS frontend: $tls (use caddy or nginx)"
      ;;
  esac
}
